import{z as s,x as A,o as e,c as B,q as t,j as n,D as E,d as i,s as l,S as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"故障注入","description":"","frontmatter":{"title":"故障注入","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fault-injection.md","filePath":"cs/fault-injection.md","lastUpdated":1791063341000}'),p={name:"cs/fault-injection.md"};function d(c,a,h,D,_,m){const o=A("Mermaid");return e(),B("div",null,[a[2]||(a[2]=t('<h1 id="故障注入" tabindex="-1">故障注入 <a class="header-anchor" href="#故障注入" aria-label="Permalink to &quot;故障注入&quot;">​</a></h1><div class="epigraph"><p>电压、时钟或激光让芯片算错一轮，错误输出可能泄漏密钥或跳过校验。防护是冗余、检测与失败即关，而不是假设封装等于物理不可及。</p><footer>—— Boneh, DeMillo and Lipton, On the Importance of Checking Cryptographic Protocols for Faults, EUROCRYPT 1997</footer></div><p>上一课<a href="/cs/power-analysis-dpa">DPA</a>是被动观测功耗；缺口升级为<strong>主动让计算出错</strong>——注入电压毛刺、时钟扰动或激光，看错误输出能换来什么。本课讲故障与检测，不给注入实验步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经典失败模式是 RSA-CRT：签名分模 \\(p\\)、模 \\(q\\) 两半各算再合并，若某一半被瞬时故障扰动，错误签名与正确结果之差就是 \\(p\\)（或 \\(q\\)）的倍数，一次 gcd 即分解模数——这是 Boneh–DeMillo–Lipton 的结论。教训不是「运气差」，而是不信任自己的计算：缺口是冗余设计与故障传感器。</p>',6)),(e(),n(r,null,{default:E(()=>[l(o,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%BE%85%E7%AD%BE%E6%B6%88%E6%81%AF%20m%22%5D%20--%3E%20H1%5B%22%E6%A8%A1%20p%20%E7%AE%97%E5%8D%8A%E8%BE%B9%E7%AD%BE%E5%90%8D%22%5D%0A%20%20M%20--%3E%20H2%5B%22%E6%A8%A1%20q%20%E7%AE%97%E5%8F%A6%E4%B8%80%E5%8D%8A%22%5D%0A%20%20FA%5B%22%E7%9E%AC%E6%97%B6%E6%95%85%E9%9A%9C%E6%89%B0%E5%8A%A8%E5%85%B6%E4%B8%AD%E4%B8%80%E5%8D%8A%22%5D%20--%3E%20H1%0A%20%20H1%20--%3E%20C%5B%22%E5%90%88%E5%B9%B6%E5%87%BA%E6%9C%80%E7%BB%88%E7%AD%BE%E5%90%8D%22%5D%0A%20%20H2%20--%3E%20C%0A%20%20C%20--%3E%20BAD%5B%22%E8%AE%BE%E5%A4%87%E8%BE%93%E5%87%BA%E9%94%99%E8%AF%AF%E7%AD%BE%E5%90%8D%20s'%22%5D%0A%20%20BAD%20--%3E%20G%5B%22%E6%94%BB%E5%87%BB%E8%80%85%E5%AF%B9%20s'%20%E7%9A%84%20e%20%E6%AC%A1%E6%96%B9%E5%87%8F%20m%20%E4%B8%8E%20N%20%E6%B1%82%20gcd%22%5D%0A%20%20G%20--%3E%20F%5B%22%E5%B7%AE%E5%80%BC%E6%81%B0%E6%98%AF%20p%20%E7%9A%84%E5%80%8D%E6%95%B0%2C%20%E6%A8%A1%E6%95%B0%E8%A2%AB%E5%88%86%E8%A7%A3%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">术语翻译：CRT（中国剩余定理）在这里就是把一个大数运算拆成模 \\(p\\)、模 \\(q\\) 两个小数各算一遍再合并，速度约快 4 倍。数字实例：2048 位的 \\(N\\) 拆成两个 1024 位的半边——模乘代价与位数近似立方相关，位数减半，每边只剩约八分之一的工作量。</span></p><h3 id="安全元件" tabindex="-1">安全元件 <a class="header-anchor" href="#安全元件" aria-label="Permalink to &quot;安全元件&quot;">​</a></h3><p>安全元件认证会把故障注入交给认证实验室实测；软件栈拿到芯片后不能反过来假设它无故障——故障是概率性的，任何一次会话都可能碰上一次成功扰动。</p><p><span class="marginnote">Boneh–DeMillo–Lipton。禁止故障注入实验指导。PUF 下一课把物理不可克隆当身份。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法先把被动与主动分开：被动读泄漏，主动改状态。对策相应三件——关键运算重复一遍或双通道并行再比对（时间/空间冗余）、输出前校验（CRT 结果代回验证，开销小得多）、电压与时钟传感器发现环境异常即拒绝输出或清密钥。下一课 PUF。</p>',6)),(e(),n(r,null,{default:E(()=>[l(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAULT%5B%22%E7%8E%AF%E5%A2%83%E6%89%B0%E5%8A%A8%22%5D%20--%3E%20ERR%5B%22%E9%94%99%E8%AF%AF%E4%B8%AD%E9%97%B4%E5%80%BC%22%5D%0A%20%20ERR%20--%3E%20LEAK%5B%22%E6%88%96%E8%B7%B3%E8%BF%87%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20CHK%5B%22%E5%86%97%E4%BD%99%E6%A3%80%E6%B5%8B%22%5D%20--%3E%20FAIL%5B%22%E6%8B%92%E7%BB%9D%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制上完整性落到了物理层：密码学正确性证明默认「运算按规范执行」，故障注入破坏的正是这条前提，防线只能是计算自检——把「我真算对了吗」变成每次输出前的可执行检查。下一课 PUF 同属物理轴但模型不同：故障注入让物理干扰计算，PUF 把物理差异本身当资产。</p><p><span class="marginnote">直觉类比：CRT 代回校验就像考试做完把答案代回题目验算——只花一步乘法，比重考一遍（整个签名重算）便宜得多。这也是三件对策里开销排序的直觉：代回校验最便宜，重复计算最贵，传感器防的是环境而非算错。</span></p><p><span class="marginnote">为什么重要：如果输出前不做校验，一次毛刺就可能把私钥的因子直接送到攻击者手里——不是「这次签名不对」的小问题，而是密钥当场作废级别的事故。安全工程师把「输出前验证」当成硬性 checklist 项，原因就在这里。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>零实验配方；边界要点名：冗余不是万能——攻击者可以两次注入相同的故障骗过比对，校验逻辑自身也要进威胁模型。PUF 下一课。</p><p><span class="marginnote">常见误区：初学者容易以为「算两遍再比对」就万无一失。实际上比对能拦住随机故障，拦不住刻意构造的相同故障——两遍被同一毛刺打歪，结果照样一致地错。所以校验电路本身也得有冗余或屏蔽，否则它就是整条防线的单点。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DPA 被动；故障主动改计算。</li><li>错误输出可伤密钥；要校验。</li><li>封装不是物理不可及证明。</li><li>下一课 PUF。</li><li>出处：Boneh, DeMillo and Lipton, 1997。</li></ul>',9))])}const T=s(p,[["render",d]]);export{f as __pageData,T as default};
